// Kontrollerar SM-18 "Kanaler" (/grenar): åtta grupper i rätt ordning, märkning, inga externa resurser,
// bara de länkar som finns i dag, ingen UTM, inga datum, och F34: interna länkar utan .html.
// AI-skapat (B-051). Generated by AI, Directed by MS.
const fs = require('fs');
const html = fs.readFileSync('public/grenar.html', 'utf8');
const utanKommentarer = html.replace(/<!--[\s\S]*?-->/g, '');
const grenar = [...utanKommentarer.matchAll(/data-gren="([^"]+)"/g)].map((m) => m[1]);
const externa = [...utanKommentarer.matchAll(/href="(https?:\/\/[^"]+)"/g)].map((m) => m[1]).sort();
const tillatna = ['https://systemicactions.com/', 'https://www.instagram.com/luminus.loom1/', 'https://www.regenerativevoices.com/'];
const krav = {
  svenska: /<html lang="sv">/.test(html),
  titel: /<title>Kanaler – luminusloom\.net<\/title>/.test(html),
  hopplankForst: html.indexOf('class="hoppa"') > -1 && html.indexOf('class="hoppa"') < html.indexOf('<header'),
  attaGrenarIOrdning: grenar.join(',') === 'luminus-loom,luminus-301,regenerative-voices,systemic-actions,karavanen,ek-och-lin,leonid,vreta-kok',
  engelskRadPerGrupp: (utanKommentarer.match(/<p class="en" lang="en">/g) || []).length >= 9,
  aiEtiketter: (html.match(/class="etikett">AI-skapat</g) || []).length >= 2,
  signatur: (html.match(/Generated by AI, Directed by MS/g) || []).length >= 2,
  baraLankarSomFinns: JSON.stringify(externa) === JSON.stringify(tillatna),
  lankAiSida: utanKommentarer.includes('href="/sa-marker-vi-ai"'),
  ingenUtm: !/utm_/.test(utanKommentarer),
  ingaDatum: !/\b20\d\d\b/.test(utanKommentarer),
  ingaExternaResurser: !/src="https?:\/\//.test(html) && !/@import|url\(/.test(html),
  ingetSkript: !/<script/i.test(html),
  ingenLagring: !/localStorage|sessionStorage|document\.cookie/.test(html),
  sammaFlik: !/target=/.test(utanKommentarer),
  morktLage: html.includes('prefers-color-scheme: dark'),
  renaLankar: !/href="\/[^"]*\.html"/.test(utanKommentarer),
};
const ok = Object.values(krav).every(Boolean);
console.log(JSON.stringify({ ...krav, ok }));
process.exit(ok ? 0 : 1);
